# Empty __init__.py
EMPTY = [
    "backend/app/__init__.py",
    "backend/app/agents/__init__.py",
    "backend/app/rag/__init__.py",
    "backend/app/docx_gen/__init__.py",
]

def write_file(rel_path, content_bytes):
    dest = ROOT / rel_path
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_bytes(content_bytes)

# Write all files
n = len(FILES) + len(EMPTY)
for i, (rel, b64_data) in enumerate(FILES.items(), 1):
    if isinstance(b64_data, tuple):
        b64_data = "".join(b64_data)
    write_file(rel, base64.b64decode(b64_data))
    print(f"  [{i}/{n}] {rel}")

for i, rel in enumerate(EMPTY, len(FILES) + 1):
    write_file(rel, b"")
    print(f"  [{i}/{n}] {rel}")

print()
